#!/usr/bin/env bash
# Publishes a maintenance result (run.sh's result directory) from a job
# that has write access but no API keys and runs no agent: applies the
# patch to the checkout in the working directory, commits it, and either
# opens a pull request (MODE=create) or pushes to the existing one and
# replies with the agent's message (MODE=update).
#
# Environment:
#   GH_TOKEN, GITHUB_REPOSITORY, GITHUB_SERVER_URL
#   RESULT_DIR      meta.json, summary.md and (when changed) changes.patch
#   MODE            create | update
#   PR              update: the pull request number
#   ROUND           update: the review round, for the commit subject
#   BRANCH_PREFIX   create: new branches are <prefix><date>-<run id>
#   BASE_BRANCH     create: the pull request's base branch
#   PR_DRAFT        create: "true" opens a draft
#   PR_LABELS       create: comma-separated labels (missing labels are skipped)
#   RUN_URL         link to the workflow run, for the footer
#   GIT_AUTHOR_NAME, GIT_AUTHOR_EMAIL   commit identity (default github-actions[bot])
#
# Outputs (GITHUB_OUTPUT): pr-number, pr-url, branch, published-at.
set -euo pipefail

here=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source=lib.sh
. "$here/lib.sh"

out() { [ -n "${GITHUB_OUTPUT:-}" ] && printf '%s=%s\n' "$1" "$2" >>"$GITHUB_OUTPUT"; return 0; }

: "${RESULT_DIR:?}" "${MODE:?}" "${GITHUB_REPOSITORY:?}"
meta=$RESULT_DIR/meta.json
patch=$RESULT_DIR/changes.patch
[ -f "$meta" ] || { ai_log "no result metadata in $RESULT_DIR"; exit 2; }
status=$(jq -r .status "$meta")
provider=$(jq -r .provider "$meta")
model=$(jq -r '.model // ""' "$meta")
effort=$(jq -r '.effort // ""' "$meta")
# "claude (model m, effort high)" for the footer and the commit message.
run_by=$provider
if [ -n "$model$effort" ]; then
    run_by="$provider ($(printf '%s' "${model:+model $model}${model:+${effort:+, }}${effort:+effort $effort}"))"
fi
title=$(jq -r .title "$meta")
base_sha=$(jq -r .base_sha "$meta")
MARKER='<!-- ai-maintenance -->'

export GIT_AUTHOR_NAME=${GIT_AUTHOR_NAME:-github-actions[bot]}
export GIT_AUTHOR_EMAIL=${GIT_AUTHOR_EMAIL:-41898282+github-actions[bot]@users.noreply.github.com}
export GIT_COMMITTER_NAME=$GIT_AUTHOR_NAME GIT_COMMITTER_EMAIL=$GIT_AUTHOR_EMAIL

# The patch was made against base_sha; the branch must not have moved.
if [ "$(git rev-parse HEAD)" != "$base_sha" ]; then
    ai_log "checkout is at $(git rev-parse HEAD), but the agent worked on $base_sha; not publishing"
    exit 1
fi

body=$(mktemp)
trap 'rm -f "$body"' EXIT
{
    cat "$RESULT_DIR/summary.md"
    printf '\n\n---\n<sub>Generated by the AI maintenance workflow with %s' "$run_by"
    [ -n "${RUN_URL:-}" ] && printf ' · [workflow run](%s)' "$RUN_URL"
    printf '</sub>\n%s\n' "$MARKER"
} >"$body"

push() { # refspec
    local server=${GITHUB_SERVER_URL:-https://github.com} auth
    auth=$(printf 'x-access-token:%s' "${GH_TOKEN:?}" | base64 | tr -d '\n')
    [ "${GITHUB_ACTIONS:-}" = true ] && echo "::add-mask::$auth"
    git -c "http.$server/.extraheader=AUTHORIZATION: basic $auth" push origin "$1"
}

commit() { # subject
    git apply --index --binary --whitespace=nowarn "$patch"
    git commit -q -m "$1" -m "Generated by the AI maintenance workflow with $run_by.${RUN_URL:+

Run: $RUN_URL}" -m "AI-Maintenance-Provider: $provider"
}

now=$(date -u +%FT%TZ)
case "$MODE" in
    create)
        if [ "$status" != changed ] || [ ! -s "$patch" ]; then
            ai_log "nothing to publish (status $status)"
            exit 0
        fi
        : "${BRANCH_PREFIX:?}" "${BASE_BRANCH:?}"
        branch="${BRANCH_PREFIX}$(date -u +%Y%m%d)-${GITHUB_RUN_ID:-local}"
        git checkout -q -b "$branch"
        commit "$title"
        push "HEAD:refs/heads/$branch"
        args=(--repo "$GITHUB_REPOSITORY" --base "$BASE_BRANCH" --head "$branch"
            --title "$title" --body-file "$body")
        [ "${PR_DRAFT:-false}" = true ] && args+=(--draft)
        url=$(gh pr create "${args[@]}")
        number=${url##*/}
        IFS=',' read -ra labels <<<"${PR_LABELS:-}"
        for l in "${labels[@]}"; do
            l=$(printf '%s' "$l" | sed 's/^ *//; s/ *$//')
            [ -n "$l" ] || continue
            gh pr edit "$number" --repo "$GITHUB_REPOSITORY" --add-label "$l" >/dev/null 2>&1 ||
                ai_log "could not add label '$l' (does it exist?)"
        done
        ai_log "opened $url"
        out pr-number "$number"
        out pr-url "$url"
        out branch "$branch"
        ;;
    update)
        : "${PR:?}"
        branch=$(git symbolic-ref -q --short HEAD) || { ai_log "update needs the PR branch checked out"; exit 2; }
        if [ "$status" = changed ] && [ -s "$patch" ]; then
            commit "Address review feedback (round ${ROUND:-1})"
            push "HEAD:refs/heads/$branch"
            printf '\n<sub>Pushed %s.</sub>\n' "$(git rev-parse --short HEAD)" >>"$body"
        fi
        gh pr comment "$PR" --repo "$GITHUB_REPOSITORY" --body-file "$body" >/dev/null
        ai_log "replied on PR #$PR (status $status)"
        out pr-number "$PR"
        out branch "$branch"
        ;;
    *)
        ai_log "MODE must be create or update"
        exit 2
        ;;
esac
out published-at "$now"
